<?php
require_once 'includes/config.php';require_once 'includes/functions.php';$page_title='Traveller reviews';
if($_SERVER['REQUEST_METHOD']==='POST'){require_tourist();$rating=(int)($_POST['rating']??5);$comment=trim($_POST['comment']??'');$package=(int)($_POST['package_id']??0);if($rating>=1&&$rating<=5&&$comment!==''){$packageId=null;if($package>0){$check=$pdo->prepare("SELECT package_id FROM tour_packages WHERE package_id=? AND is_active=1");$check->execute([$package]);$validPackage=$check->fetchColumn();if(!$validPackage){flash('Please choose a valid tour package.','error');header('Location: reviews.php');exit;}$packageId=(int)$validPackage;}$s=$pdo->prepare("INSERT INTO reviews(tourist_id,package_id,rating,review_comment,review_date) VALUES(?,?,?,?,CURDATE())");$s->execute([(int)$_SESSION['tourist_id'],$packageId,$rating,$comment]);flash('Thank you for sharing your experience.');header('Location: reviews.php');exit;}flash('Please select a rating and write a comment.','error');header('Location: reviews.php');exit;}
$reviews=$pdo->query("SELECT r.*,t.first_name,t.last_name,p.package_name FROM reviews r JOIN tourists t ON t.tourist_id=r.tourist_id LEFT JOIN tour_packages p ON p.package_id=r.package_id ORDER BY r.review_id DESC")->fetchAll();$packages=$pdo->query("SELECT package_id,package_name FROM tour_packages WHERE is_active=1 ORDER BY package_name")->fetchAll();require 'includes/header.php';?>
<section class="section account-page-section"><div class="container account-layout"><div class="account-sidebar-card"><?php require 'includes/account_sidebar.php'; ?></div><div class="account-content-card account-reviews-content"><span class="eyebrow">Stories from travellers</span><h1>Traveller reviews</h1><p>Read feedback shared by the TravelHub community and add your own experience.</p><?php if(logged_in()&&!is_admin()): ?><form class="form-shell" method="post"><h2>Share your experience</h2><div class="form-grid"><div class="field"><label>Tour package (optional)</label><select name="package_id"><option value="0">General TravelHub experience</option><?php foreach($packages as $p): ?><option value="<?= (int)$p['package_id'] ?>"><?= e($p['package_name']) ?></option><?php endforeach; ?></select></div><div class="field"><label>Rating</label><select name="rating"><option value="5">★★★★★ — Excellent</option><option value="4">★★★★ — Very good</option><option value="3">★★★ — Good</option><option value="2">★★ — Fair</option><option value="1">★ — Poor</option></select></div><div class="field full"><label>Your review</label><textarea name="comment" required maxlength="1500" placeholder="What made your trip special?"></textarea></div></div><div class="form-actions"><button class="btn">Submit review</button></div></form><?php elseif(!logged_in()): ?><div class="notice">Want to leave a review? <a class="text-link" href="login.php">Log in to your account</a> first.</div><?php endif; ?>
<?php if(!$reviews): ?><div class="empty-state"><h3>Be the first to share a story</h3><p>Traveller reviews will appear here once submitted.</p></div><?php else: ?><div class="grid-3"><?php foreach($reviews as $r): ?><article class="review-card"><div class="stars"><?= str_repeat('★',(int)$r['rating']).str_repeat('☆',5-(int)$r['rating']) ?></div><p>“<?= e($r['review_comment']) ?>”</p><div class="card-meta"><div><strong><?= e($r['first_name'].' '.$r['last_name']) ?></strong><br><small class="muted"><?= e($r['package_name']??'TravelHub traveller') ?></small></div><small class="muted"><?= e($r['review_date']) ?></small></div></article><?php endforeach; ?></div><?php endif; ?></div></div></section>
<?php require 'includes/footer.php'; ?>
